using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Returns a greeting for the given name.")]
    public static string Greet(string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";
}

using ModelContextProtocol.Server;
using System.Text.Json;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new[] { "tools", "resources" }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/env", Name = "Environment",
        MimeType = "text/plain")]
    public static string GetEnvironment() =>
        Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production";
}

